-- sql/40_facts/01_fact_loads.sql: the fact load scripts (E7, US-7.1 to US-7.4)
-- GENERATED by scripts/export_load_sql.py from etl/facts/spec.py: do not edit by hand; change the
-- spec and re-export (make test fails while this file and the loader differ).
--
-- Every fact is synced on its grain, so a rerun inserts, updates and deletes nothing (D14):
--   the source query (staging joined to the dimensions, keys point in time) into _fact_src;
--   rows missing a required measure are rejected (deleted from _fact_src, counted by the loader);
--   DELETE the fact rows whose grain left the source; UPDATE the rows whose values differ (an
--   accumulating snapshot's next milestone); INSERT the grains not in the fact yet.
-- The periodic snapshot (fact_unit_occupancy_daily, US-7.3) is loaded for the data window
-- 2023-07-01 to 2026-06-30, then its last refresh days are deleted and re-derived (the one
-- declared exception of D14). The loader runs it month by month (one partition per statement);
-- here it is one pass over the window, with the same result.
-- The pipeline runs these statements through etl/facts/load.py (python etl/facts/run.py), one
-- transaction per fact, and adds: it refuses a source with a grain twice, or a primary-key column
-- unresolved (-1); counts rejected rows and unresolved keys; reconciles each fact to staging by
-- month (US-7.2); runs the fact tests (sql/90_tests/02_fact_tests.sql); logs to lue_audit.
-- Run by hand after the dimensions (it is one transaction):
--   psql -d lue_warehouse -v ON_ERROR_STOP=1 -f sql/40_facts/01_fact_loads.sql

BEGIN;
SELECT set_config('lue.run_id', nextval('lue_audit.seq_run_id')::text, false),
       set_config('lue.loaded_at', date_trunc('second', localtimestamp)::text, false);

-- ------------------------------------------------------------------------------------------------
-- fact_rent_invoice_line (US-7.2): grain invoice_number, invoice_line_no
-- ------------------------------------------------------------------------------------------------
-- the source: one row per grain
DROP TABLE IF EXISTS _fact_src;
CREATE TEMP TABLE _fact_src ON COMMIT DROP AS
        SELECT CASE WHEN i.invoice_date IS NULL THEN -1 WHEN (i.invoice_date)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((i.invoice_date)::date, 'YYYYMMDD')::int ELSE -1 END AS invoice_date_key,
               CASE WHEN coalesce(il.due_date, i.due_date) IS NULL THEN -1 WHEN (coalesce(il.due_date, i.due_date))::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((coalesce(il.due_date, i.due_date))::date, 'YYYYMMDD')::int ELSE -1 END AS due_date_key,
               coalesce(du.unit_key, -1) AS unit_key,
               coalesce(dt.tenant_key, -1) AS tenant_key,
               coalesce(dl.lease_key, -1) AS lease_key,
               coalesce(dw.owner_key, -1) AS owner_key,
               coalesce(dc.charge_type_key, -1) AS charge_type_key,
               il.invoice_number, il.line_no AS invoice_line_no,
               il.billed_amount, il.tax_amount, il.discount_amount, il.net_amount,
               'S1' AS source_system
        FROM lue_staging.stg_invoice_line il
        LEFT JOIN lue_staging.stg_invoice i ON i.invoice_number = il.invoice_number
        LEFT JOIN lue_staging.stg_lease sl ON sl.lease_number = i.lease_number
        LEFT JOIN lue_staging.stg_unit su ON su.unit_id = sl.unit_id
        LEFT JOIN lue_dw.dim_unit du ON du.unit_nk = su.building_code || '-' || su.unit_no AND (i.invoice_date)::date >= du.effective_from AND (i.invoice_date)::date < du.effective_to
        LEFT JOIN lue_dw.dim_tenant dt ON dt.tenant_code = sl.tenant_code AND (i.invoice_date)::date >= dt.effective_from AND (i.invoice_date)::date < dt.effective_to
        LEFT JOIN lue_dw.dim_lease dl ON dl.lease_number = i.lease_number
        LEFT JOIN lue_staging.stg_ownership dw_r ON dw_r.building_code = su.building_code AND dw_r.unit_no = su.unit_no AND dw_r.valid_from <= (i.invoice_date)::date AND (dw_r.valid_to IS NULL OR (i.invoice_date)::date < dw_r.valid_to) LEFT JOIN lue_dw.dim_owner dw ON dw.owner_code = dw_r.owner_code
        LEFT JOIN lue_dw.dim_charge_type dc ON dc.charge_code = il.charge_code;
-- rows without billed_amount, tax_amount, discount_amount, net_amount are rejected
DELETE FROM _fact_src WHERE billed_amount IS NULL OR tax_amount IS NULL OR discount_amount IS NULL OR net_amount IS NULL;
-- sync on the grain: grains gone, values changed, grains new
DELETE FROM lue_dw.fact_rent_invoice_line x WHERE NOT EXISTS (SELECT 1 FROM _fact_src s WHERE s.invoice_number = x.invoice_number AND s.invoice_line_no = x.invoice_line_no);
UPDATE lue_dw.fact_rent_invoice_line x SET invoice_date_key = s.invoice_date_key, due_date_key = s.due_date_key, unit_key = s.unit_key, tenant_key = s.tenant_key, lease_key = s.lease_key, owner_key = s.owner_key, charge_type_key = s.charge_type_key, billed_amount = s.billed_amount, tax_amount = s.tax_amount, discount_amount = s.discount_amount, net_amount = s.net_amount, source_system = s.source_system, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE x.invoice_number = s.invoice_number AND x.invoice_line_no = s.invoice_line_no AND (x.invoice_date_key, x.due_date_key, x.unit_key, x.tenant_key, x.lease_key, x.owner_key, x.charge_type_key, x.billed_amount, x.tax_amount, x.discount_amount, x.net_amount, x.source_system) IS DISTINCT FROM (s.invoice_date_key, s.due_date_key, s.unit_key, s.tenant_key, s.lease_key, s.owner_key, s.charge_type_key, s.billed_amount, s.tax_amount, s.discount_amount, s.net_amount, s.source_system);
INSERT INTO lue_dw.fact_rent_invoice_line (invoice_date_key, due_date_key, unit_key, tenant_key, lease_key, owner_key, charge_type_key, invoice_number, invoice_line_no, billed_amount, tax_amount, discount_amount, net_amount, source_system, batch_id, loaded_at) SELECT s.invoice_date_key, s.due_date_key, s.unit_key, s.tenant_key, s.lease_key, s.owner_key, s.charge_type_key, s.invoice_number, s.invoice_line_no, s.billed_amount, s.tax_amount, s.discount_amount, s.net_amount, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.fact_rent_invoice_line x WHERE x.invoice_number = s.invoice_number AND x.invoice_line_no = s.invoice_line_no) ORDER BY s.invoice_number, s.invoice_line_no;
DROP TABLE IF EXISTS _fact_src;

-- ------------------------------------------------------------------------------------------------
-- fact_payment (US-7.1): grain payment_reference, invoice_number, invoice_line_no
-- ------------------------------------------------------------------------------------------------
-- the source: one row per grain
DROP TABLE IF EXISTS _fact_src;
CREATE TEMP TABLE _fact_src ON COMMIT DROP AS
        SELECT CASE WHEN p.paid_at IS NULL THEN -1 WHEN (p.paid_at)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((p.paid_at)::date, 'YYYYMMDD')::int ELSE -1 END AS paid_date_key,
               CASE WHEN il.due_date IS NULL THEN -1 WHEN (il.due_date)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((il.due_date)::date, 'YYYYMMDD')::int ELSE -1 END AS due_date_key,
               coalesce(du.unit_key, -1) AS unit_key,
               coalesce(dt.tenant_key, -1) AS tenant_key,
               coalesce(dl.lease_key, -1) AS lease_key,
               coalesce(dw.owner_key, -1) AS owner_key,
               coalesce(dm.payment_method_key, -1) AS payment_method_key,
               coalesce(dc.charge_type_key, -1) AS charge_type_key,
               a.payment_reference, a.invoice_number, a.line_no AS invoice_line_no,
               a.allocated_amount AS payment_amount, a.days_past_due, p.settlement_lag_days,
               a.is_reversal, 'S1' AS source_system
        FROM lue_staging.stg_payment_allocation a
        JOIN lue_staging.stg_payment p USING (payment_reference)
        LEFT JOIN lue_staging.stg_invoice_line il ON il.invoice_number = a.invoice_number AND il.line_no = a.line_no
        LEFT JOIN lue_staging.stg_invoice i ON i.invoice_number = a.invoice_number
        LEFT JOIN lue_staging.stg_lease sl ON sl.lease_number = i.lease_number
        LEFT JOIN lue_staging.stg_unit su ON su.unit_id = sl.unit_id
        LEFT JOIN lue_dw.dim_unit du ON du.unit_nk = su.building_code || '-' || su.unit_no AND (p.paid_at)::date >= du.effective_from AND (p.paid_at)::date < du.effective_to
        LEFT JOIN lue_dw.dim_tenant dt ON dt.tenant_code = p.tenant_code AND (p.paid_at)::date >= dt.effective_from AND (p.paid_at)::date < dt.effective_to
        LEFT JOIN lue_dw.dim_lease dl ON dl.lease_number = i.lease_number
        LEFT JOIN lue_staging.stg_ownership dw_r ON dw_r.building_code = su.building_code AND dw_r.unit_no = su.unit_no AND dw_r.valid_from <= (p.paid_at)::date AND (dw_r.valid_to IS NULL OR (p.paid_at)::date < dw_r.valid_to) LEFT JOIN lue_dw.dim_owner dw ON dw.owner_code = dw_r.owner_code
        LEFT JOIN lue_dw.dim_payment_method dm ON dm.method_code = p.method_code
        LEFT JOIN lue_dw.dim_charge_type dc ON dc.charge_code = il.charge_code;
-- rows without payment_amount, days_past_due, is_reversal are rejected
DELETE FROM _fact_src WHERE payment_amount IS NULL OR days_past_due IS NULL OR is_reversal IS NULL;
-- sync on the grain: grains gone, values changed, grains new
DELETE FROM lue_dw.fact_payment x WHERE NOT EXISTS (SELECT 1 FROM _fact_src s WHERE s.payment_reference = x.payment_reference AND s.invoice_number = x.invoice_number AND s.invoice_line_no = x.invoice_line_no);
UPDATE lue_dw.fact_payment x SET paid_date_key = s.paid_date_key, due_date_key = s.due_date_key, unit_key = s.unit_key, tenant_key = s.tenant_key, lease_key = s.lease_key, owner_key = s.owner_key, payment_method_key = s.payment_method_key, charge_type_key = s.charge_type_key, payment_amount = s.payment_amount, days_past_due = s.days_past_due, settlement_lag_days = s.settlement_lag_days, is_reversal = s.is_reversal, source_system = s.source_system, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE x.payment_reference = s.payment_reference AND x.invoice_number = s.invoice_number AND x.invoice_line_no = s.invoice_line_no AND (x.paid_date_key, x.due_date_key, x.unit_key, x.tenant_key, x.lease_key, x.owner_key, x.payment_method_key, x.charge_type_key, x.payment_amount, x.days_past_due, x.settlement_lag_days, x.is_reversal, x.source_system) IS DISTINCT FROM (s.paid_date_key, s.due_date_key, s.unit_key, s.tenant_key, s.lease_key, s.owner_key, s.payment_method_key, s.charge_type_key, s.payment_amount, s.days_past_due, s.settlement_lag_days, s.is_reversal, s.source_system);
INSERT INTO lue_dw.fact_payment (paid_date_key, due_date_key, unit_key, tenant_key, lease_key, owner_key, payment_method_key, charge_type_key, payment_reference, invoice_number, invoice_line_no, payment_amount, days_past_due, settlement_lag_days, is_reversal, source_system, batch_id, loaded_at) SELECT s.paid_date_key, s.due_date_key, s.unit_key, s.tenant_key, s.lease_key, s.owner_key, s.payment_method_key, s.charge_type_key, s.payment_reference, s.invoice_number, s.invoice_line_no, s.payment_amount, s.days_past_due, s.settlement_lag_days, s.is_reversal, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.fact_payment x WHERE x.payment_reference = s.payment_reference AND x.invoice_number = s.invoice_number AND x.invoice_line_no = s.invoice_line_no) ORDER BY s.payment_reference, s.invoice_number, s.invoice_line_no;
DROP TABLE IF EXISTS _fact_src;

-- ------------------------------------------------------------------------------------------------
-- fact_maintenance_request (US-7.4): grain request_number
-- ------------------------------------------------------------------------------------------------
-- the source: one row per grain
DROP TABLE IF EXISTS _fact_src;
CREATE TEMP TABLE _fact_src ON COMMIT DROP AS
        SELECT CASE WHEN t.raised_at IS NULL THEN -1 WHEN (t.raised_at)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((t.raised_at)::date, 'YYYYMMDD')::int ELSE -1 END AS raised_date_key,
               CASE WHEN t.assigned_at IS NULL THEN -2 WHEN (t.assigned_at)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((t.assigned_at)::date, 'YYYYMMDD')::int ELSE -1 END AS assigned_date_key,
               CASE WHEN t.resolved_at IS NULL THEN -2 WHEN (t.resolved_at)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((t.resolved_at)::date, 'YYYYMMDD')::int ELSE -1 END AS resolved_date_key,
               CASE WHEN t.verified_at IS NULL THEN -2 WHEN (t.verified_at)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((t.verified_at)::date, 'YYYYMMDD')::int ELSE -1 END AS verified_date_key,
               coalesce(du.unit_key, -1) AS unit_key,
               CASE WHEN sl.lease_number IS NULL THEN -2 ELSE coalesce(dt.tenant_key, -1) END AS tenant_key,
               coalesce(dw.owner_key, -1) AS owner_key,
               coalesce(dc.maint_category_key, -1) AS maint_category_key,
               CASE WHEN t.assigned_at IS NULL THEN -2 ELSE coalesce(dv.vendor_key, -1) END AS vendor_key,
               coalesce(df.request_flags_key, -1) AS request_flags_key,
               coalesce(dx.weather_key, -1) AS weather_key,
               t.ticket_id AS request_number, t.status AS request_status,
               t.days_to_assign, t.days_to_resolve, t.days_to_verify, t.estimated_cost, t.actual_cost,
               CASE WHEN t.resolved_at IS NULL OR dc.default_sla_hours IS NULL THEN NULL
                    WHEN t.hours_to_resolve > dc.default_sla_hours THEN 1 ELSE 0 END::smallint AS sla_breached_flag,
               'S4' AS source_system
        FROM lue_staging.stg_ticket t
        LEFT JOIN lue_staging.stg_unit su ON su.building_code = t.building_code AND su.unit_no = t.unit_no
        LEFT JOIN lue_staging.stg_lease sl ON sl.unit_id = su.unit_id AND t.raised_at::date BETWEEN sl.start_date AND sl.end_date
        LEFT JOIN lue_dw.dim_unit du ON du.unit_nk = t.building_code || '-' || t.unit_no AND (t.raised_at)::date >= du.effective_from AND (t.raised_at)::date < du.effective_to
        LEFT JOIN lue_dw.dim_tenant dt ON dt.tenant_code = sl.tenant_code AND (t.raised_at)::date >= dt.effective_from AND (t.raised_at)::date < dt.effective_to
        LEFT JOIN lue_staging.stg_ownership dw_r ON dw_r.building_code = t.building_code AND dw_r.unit_no = t.unit_no AND dw_r.valid_from <= (t.raised_at)::date AND (dw_r.valid_to IS NULL OR (t.raised_at)::date < dw_r.valid_to) LEFT JOIN lue_dw.dim_owner dw ON dw.owner_code = dw_r.owner_code
        LEFT JOIN lue_dw.dim_maintenance_category dc ON dc.subcategory_code = t.subcategory_code AND (t.raised_at)::date >= dc.effective_from AND (t.raised_at)::date < dc.effective_to
        LEFT JOIN lue_dw.dim_vendor dv ON dv.vendor_code = t.vendor_code AND (t.assigned_at)::date >= dv.effective_from AND (t.assigned_at)::date < dv.effective_to
        LEFT JOIN lue_dw.dim_request_flags df ON df.is_emergency = t.is_emergency AND df.is_recurring = t.is_recurring AND df.is_tenant_caused = t.is_tenant_caused
        LEFT JOIN lue_dw.dim_weather dx ON dx.city = du.city AND dx.weather_date = (t.raised_at)::date;
-- rows without request_status are rejected
DELETE FROM _fact_src WHERE request_status IS NULL;
-- sync on the grain: grains gone, values changed, grains new
DELETE FROM lue_dw.fact_maintenance_request x WHERE NOT EXISTS (SELECT 1 FROM _fact_src s WHERE s.request_number = x.request_number);
UPDATE lue_dw.fact_maintenance_request x SET raised_date_key = s.raised_date_key, assigned_date_key = s.assigned_date_key, resolved_date_key = s.resolved_date_key, verified_date_key = s.verified_date_key, unit_key = s.unit_key, tenant_key = s.tenant_key, owner_key = s.owner_key, maint_category_key = s.maint_category_key, vendor_key = s.vendor_key, request_flags_key = s.request_flags_key, weather_key = s.weather_key, request_status = s.request_status, days_to_assign = s.days_to_assign, days_to_resolve = s.days_to_resolve, days_to_verify = s.days_to_verify, estimated_cost = s.estimated_cost, actual_cost = s.actual_cost, sla_breached_flag = s.sla_breached_flag, source_system = s.source_system, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE x.request_number = s.request_number AND (x.raised_date_key, x.assigned_date_key, x.resolved_date_key, x.verified_date_key, x.unit_key, x.tenant_key, x.owner_key, x.maint_category_key, x.vendor_key, x.request_flags_key, x.weather_key, x.request_status, x.days_to_assign, x.days_to_resolve, x.days_to_verify, x.estimated_cost, x.actual_cost, x.sla_breached_flag, x.source_system) IS DISTINCT FROM (s.raised_date_key, s.assigned_date_key, s.resolved_date_key, s.verified_date_key, s.unit_key, s.tenant_key, s.owner_key, s.maint_category_key, s.vendor_key, s.request_flags_key, s.weather_key, s.request_status, s.days_to_assign, s.days_to_resolve, s.days_to_verify, s.estimated_cost, s.actual_cost, s.sla_breached_flag, s.source_system);
INSERT INTO lue_dw.fact_maintenance_request (raised_date_key, assigned_date_key, resolved_date_key, verified_date_key, unit_key, tenant_key, owner_key, maint_category_key, vendor_key, request_flags_key, weather_key, request_number, request_status, days_to_assign, days_to_resolve, days_to_verify, estimated_cost, actual_cost, sla_breached_flag, source_system, batch_id, loaded_at) SELECT s.raised_date_key, s.assigned_date_key, s.resolved_date_key, s.verified_date_key, s.unit_key, s.tenant_key, s.owner_key, s.maint_category_key, s.vendor_key, s.request_flags_key, s.weather_key, s.request_number, s.request_status, s.days_to_assign, s.days_to_resolve, s.days_to_verify, s.estimated_cost, s.actual_cost, s.sla_breached_flag, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.fact_maintenance_request x WHERE x.request_number = s.request_number) ORDER BY s.request_number;
DROP TABLE IF EXISTS _fact_src;

-- ------------------------------------------------------------------------------------------------
-- fact_lease_event (US-7.5): grain lease_key, lease_event_type_key, event_date_key
-- ------------------------------------------------------------------------------------------------
-- the source: one row per grain
DROP TABLE IF EXISTS _fact_src;
CREATE TEMP TABLE _fact_src ON COMMIT DROP AS
        SELECT CASE WHEN e.event_date IS NULL THEN -1 WHEN (e.event_date)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((e.event_date)::date, 'YYYYMMDD')::int ELSE -1 END AS event_date_key,
               coalesce(du.unit_key, -1) AS unit_key,
               coalesce(dt.tenant_key, -1) AS tenant_key,
               coalesce(dl.lease_key, -1) AS lease_key,
               coalesce(dw.owner_key, -1) AS owner_key,
               coalesce(de.lease_event_type_key, -1) AS lease_event_type_key,
               1::smallint AS event_count,
               'S1' AS source_system
        FROM lue_staging.stg_lease_event e
        LEFT JOIN lue_staging.stg_lease sl ON sl.lease_number = e.lease_number
        LEFT JOIN lue_staging.stg_unit su ON su.unit_id = sl.unit_id
        LEFT JOIN lue_dw.dim_unit du ON du.unit_nk = su.building_code || '-' || su.unit_no AND (e.event_date)::date >= du.effective_from AND (e.event_date)::date < du.effective_to
        LEFT JOIN lue_dw.dim_tenant dt ON dt.tenant_code = sl.tenant_code AND (e.event_date)::date >= dt.effective_from AND (e.event_date)::date < dt.effective_to
        LEFT JOIN lue_dw.dim_lease dl ON dl.lease_number = e.lease_number
        LEFT JOIN lue_staging.stg_ownership dw_r ON dw_r.building_code = su.building_code AND dw_r.unit_no = su.unit_no AND dw_r.valid_from <= (e.event_date)::date AND (dw_r.valid_to IS NULL OR (e.event_date)::date < dw_r.valid_to) LEFT JOIN lue_dw.dim_owner dw ON dw.owner_code = dw_r.owner_code
        LEFT JOIN lue_dw.dim_lease_event_type de ON de.event_code = e.event_code;
-- sync on the grain: grains gone, values changed, grains new
DELETE FROM lue_dw.fact_lease_event x WHERE NOT EXISTS (SELECT 1 FROM _fact_src s WHERE s.lease_key = x.lease_key AND s.lease_event_type_key = x.lease_event_type_key AND s.event_date_key = x.event_date_key);
UPDATE lue_dw.fact_lease_event x SET unit_key = s.unit_key, tenant_key = s.tenant_key, owner_key = s.owner_key, event_count = s.event_count, source_system = s.source_system, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE x.lease_key = s.lease_key AND x.lease_event_type_key = s.lease_event_type_key AND x.event_date_key = s.event_date_key AND (x.unit_key, x.tenant_key, x.owner_key, x.event_count, x.source_system) IS DISTINCT FROM (s.unit_key, s.tenant_key, s.owner_key, s.event_count, s.source_system);
INSERT INTO lue_dw.fact_lease_event (event_date_key, unit_key, tenant_key, lease_key, owner_key, lease_event_type_key, event_count, source_system, batch_id, loaded_at) SELECT s.event_date_key, s.unit_key, s.tenant_key, s.lease_key, s.owner_key, s.lease_event_type_key, s.event_count, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.fact_lease_event x WHERE x.lease_key = s.lease_key AND x.lease_event_type_key = s.lease_event_type_key AND x.event_date_key = s.event_date_key) ORDER BY s.lease_key, s.lease_event_type_key, s.event_date_key;
DROP TABLE IF EXISTS _fact_src;

-- ------------------------------------------------------------------------------------------------
-- fact_vacancy_incentive_coverage (US-7.5): grain coverage_date_key, unit_key, incentive_key
-- ------------------------------------------------------------------------------------------------
-- the source: one row per grain
DROP TABLE IF EXISTS _fact_src;
CREATE TEMP TABLE _fact_src ON COMMIT DROP AS
        SELECT CASE WHEN g.day IS NULL THEN -1 WHEN (g.day)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((g.day)::date, 'YYYYMMDD')::int ELSE -1 END AS coverage_date_key,
               coalesce(du.unit_key, -1) AS unit_key,
               coalesce(di.incentive_key, -1) AS incentive_key,
               coalesce(dw.owner_key, -1) AS owner_key,
               'S6' AS source_system
        FROM lue_staging.stg_incentive_log o
        LEFT JOIN lue_staging.stg_unit su ON su.building_code = o.building_code AND su.unit_no = o.unit_no
        CROSS JOIN LATERAL (SELECT s::date AS day FROM generate_series(o.start_date, o.end_date, interval '1 day') s) g
        LEFT JOIN lue_staging.stg_lease sl ON sl.unit_id = su.unit_id AND g.day BETWEEN sl.start_date AND sl.end_date
        LEFT JOIN lue_dw.dim_unit du ON du.unit_nk = o.building_code || '-' || o.unit_no AND (g.day)::date >= du.effective_from AND (g.day)::date < du.effective_to
        LEFT JOIN lue_dw.dim_incentive di ON di.incentive_code = o.offer_code
        LEFT JOIN lue_staging.stg_ownership dw_r ON dw_r.building_code = o.building_code AND dw_r.unit_no = o.unit_no AND dw_r.valid_from <= (g.day)::date AND (dw_r.valid_to IS NULL OR (g.day)::date < dw_r.valid_to) LEFT JOIN lue_dw.dim_owner dw ON dw.owner_code = dw_r.owner_code
        WHERE sl.lease_number IS NULL;
-- sync on the grain: grains gone, values changed, grains new
DELETE FROM lue_dw.fact_vacancy_incentive_coverage x WHERE NOT EXISTS (SELECT 1 FROM _fact_src s WHERE s.coverage_date_key = x.coverage_date_key AND s.unit_key = x.unit_key AND s.incentive_key = x.incentive_key);
UPDATE lue_dw.fact_vacancy_incentive_coverage x SET owner_key = s.owner_key, source_system = s.source_system, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE x.coverage_date_key = s.coverage_date_key AND x.unit_key = s.unit_key AND x.incentive_key = s.incentive_key AND (x.owner_key, x.source_system) IS DISTINCT FROM (s.owner_key, s.source_system);
INSERT INTO lue_dw.fact_vacancy_incentive_coverage (coverage_date_key, unit_key, incentive_key, owner_key, source_system, batch_id, loaded_at) SELECT s.coverage_date_key, s.unit_key, s.incentive_key, s.owner_key, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.fact_vacancy_incentive_coverage x WHERE x.coverage_date_key = s.coverage_date_key AND x.unit_key = s.unit_key AND x.incentive_key = s.incentive_key) ORDER BY s.coverage_date_key, s.unit_key, s.incentive_key;
DROP TABLE IF EXISTS _fact_src;

-- ------------------------------------------------------------------------------------------------
-- fact_unit_occupancy_daily (US-7.3): grain snapshot_date_key, unit_key
-- ------------------------------------------------------------------------------------------------
SET LOCAL jit = off;
DROP TABLE IF EXISTS _occ_balance;
CREATE TEMP TABLE _occ_balance ON COMMIT DROP AS
             WITH line AS (SELECT il.invoice_number, il.line_no, i.lease_number, coalesce(il.due_date, i.due_date) AS due_date, il.net_amount
                           FROM lue_staging.stg_invoice_line il JOIN lue_staging.stg_invoice i USING (invoice_number)),
                  change AS (SELECT lease_number, due_date + 1 AS day, net_amount AS delta FROM line
                             UNION ALL
                             SELECT l.lease_number, greatest(l.due_date + 1, a.paid_at::date), -a.allocated_amount
                             FROM lue_staging.stg_payment_allocation a JOIN line l ON l.invoice_number = a.invoice_number AND l.line_no = a.line_no),
                  per_day AS (SELECT lease_number, day, sum(delta) AS delta FROM change GROUP BY 1, 2)
             SELECT lease_number, day AS from_day, coalesce(lead(day) OVER w, DATE '9999-12-31') AS to_day,
                    sum(delta) OVER w AS balance
             FROM per_day WINDOW w AS (PARTITION BY lease_number ORDER BY day);
ANALYZE _occ_balance;
-- the snapshot keeps the data window only
DELETE FROM lue_dw.fact_unit_occupancy_daily WHERE snapshot_date_key NOT BETWEEN 20230701 AND 20260630;
-- one pass over the window
SELECT set_config('lue.first', '2023-07-01', false), set_config('lue.last', '2026-06-30', false),
       set_config('lue.first_key', '20230701', false), set_config('lue.last_key', '20260630', false);
-- the source: one row per grain
DROP TABLE IF EXISTS _fact_src;
CREATE TEMP TABLE _fact_src ON COMMIT DROP AS
        SELECT CASE WHEN g.day IS NULL THEN -1 WHEN (g.day)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((g.day)::date, 'YYYYMMDD')::int ELSE -1 END AS snapshot_date_key,
               coalesce(du.unit_key, -1) AS unit_key,
               CASE WHEN sl.lease_number IS NULL THEN -2 ELSE coalesce(dt.tenant_key, -1) END AS tenant_key,
               CASE WHEN sl.lease_number IS NULL THEN -2 ELSE coalesce(dl.lease_key, -1) END AS lease_key,
               coalesce(dw.owner_key, -1) AS owner_key,
               (sl.lease_number IS NOT NULL)::int::smallint AS is_occupied,
               CASE WHEN sl.lease_number IS NULL THEN 0 ELSE sl.monthly_rent END AS contract_rent,
               CASE WHEN sl.lease_number IS NULL THEN 0 ELSE coalesce(b.balance, 0) END AS current_lease_arrears,
               'S1' AS source_system
        FROM lue_staging.stg_unit su
        CROSS JOIN LATERAL (SELECT s::date AS day FROM generate_series(current_setting('lue.first')::date::date, current_setting('lue.last')::date::date, interval '1 day') s) g
        LEFT JOIN lue_staging.stg_lease sl ON sl.unit_id = su.unit_id AND g.day BETWEEN sl.start_date AND sl.end_date
        LEFT JOIN _occ_balance b ON b.lease_number = sl.lease_number AND g.day >= b.from_day AND g.day < b.to_day
        LEFT JOIN lue_dw.dim_unit du ON du.unit_nk = su.building_code || '-' || su.unit_no AND (g.day)::date >= du.effective_from AND (g.day)::date < du.effective_to
        LEFT JOIN lue_dw.dim_tenant dt ON dt.tenant_code = sl.tenant_code AND (g.day)::date >= dt.effective_from AND (g.day)::date < dt.effective_to
        LEFT JOIN lue_dw.dim_lease dl ON dl.lease_number = sl.lease_number
        LEFT JOIN lue_staging.stg_ownership dw_r ON dw_r.building_code = su.building_code AND dw_r.unit_no = su.unit_no AND dw_r.valid_from <= (g.day)::date AND (dw_r.valid_to IS NULL OR (g.day)::date < dw_r.valid_to) LEFT JOIN lue_dw.dim_owner dw ON dw.owner_code = dw_r.owner_code;
-- rows without contract_rent are rejected
DELETE FROM _fact_src WHERE contract_rent IS NULL;
-- sync on the grain: grains gone, values changed, grains new
DELETE FROM lue_dw.fact_unit_occupancy_daily x WHERE NOT EXISTS (SELECT 1 FROM _fact_src s WHERE s.snapshot_date_key = x.snapshot_date_key AND s.unit_key = x.unit_key) AND x.snapshot_date_key BETWEEN current_setting('lue.first_key')::int AND current_setting('lue.last_key')::int;
UPDATE lue_dw.fact_unit_occupancy_daily x SET tenant_key = s.tenant_key, lease_key = s.lease_key, owner_key = s.owner_key, is_occupied = s.is_occupied, contract_rent = s.contract_rent, current_lease_arrears = s.current_lease_arrears, source_system = s.source_system, batch_id = current_setting('lue.run_id')::bigint, loaded_at = current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE x.snapshot_date_key = s.snapshot_date_key AND x.unit_key = s.unit_key AND x.snapshot_date_key BETWEEN current_setting('lue.first_key')::int AND current_setting('lue.last_key')::int AND (x.tenant_key, x.lease_key, x.owner_key, x.is_occupied, x.contract_rent, x.current_lease_arrears, x.source_system) IS DISTINCT FROM (s.tenant_key, s.lease_key, s.owner_key, s.is_occupied, s.contract_rent, s.current_lease_arrears, s.source_system);
INSERT INTO lue_dw.fact_unit_occupancy_daily (snapshot_date_key, unit_key, tenant_key, lease_key, owner_key, is_occupied, contract_rent, current_lease_arrears, source_system, batch_id, loaded_at) SELECT s.snapshot_date_key, s.unit_key, s.tenant_key, s.lease_key, s.owner_key, s.is_occupied, s.contract_rent, s.current_lease_arrears, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.fact_unit_occupancy_daily x WHERE x.snapshot_date_key = s.snapshot_date_key AND x.unit_key = s.unit_key AND x.snapshot_date_key BETWEEN current_setting('lue.first_key')::int AND current_setting('lue.last_key')::int) ORDER BY s.snapshot_date_key, s.unit_key;
-- the refresh: the last 35 days deleted and re-derived (D14's declared exception)
SELECT set_config('lue.first', '2026-05-27', false), set_config('lue.last', '2026-06-30', false),
       set_config('lue.first_key', '20260527', false), set_config('lue.last_key', '20260630', false);
DELETE FROM lue_dw.fact_unit_occupancy_daily WHERE snapshot_date_key BETWEEN current_setting('lue.first_key')::int AND current_setting('lue.last_key')::int;
DROP TABLE IF EXISTS _fact_src;
CREATE TEMP TABLE _fact_src ON COMMIT DROP AS
        SELECT CASE WHEN g.day IS NULL THEN -1 WHEN (g.day)::date BETWEEN DATE '2023-07-01' AND DATE '2027-06-30' THEN to_char((g.day)::date, 'YYYYMMDD')::int ELSE -1 END AS snapshot_date_key,
               coalesce(du.unit_key, -1) AS unit_key,
               CASE WHEN sl.lease_number IS NULL THEN -2 ELSE coalesce(dt.tenant_key, -1) END AS tenant_key,
               CASE WHEN sl.lease_number IS NULL THEN -2 ELSE coalesce(dl.lease_key, -1) END AS lease_key,
               coalesce(dw.owner_key, -1) AS owner_key,
               (sl.lease_number IS NOT NULL)::int::smallint AS is_occupied,
               CASE WHEN sl.lease_number IS NULL THEN 0 ELSE sl.monthly_rent END AS contract_rent,
               CASE WHEN sl.lease_number IS NULL THEN 0 ELSE coalesce(b.balance, 0) END AS current_lease_arrears,
               'S1' AS source_system
        FROM lue_staging.stg_unit su
        CROSS JOIN LATERAL (SELECT s::date AS day FROM generate_series(current_setting('lue.first')::date::date, current_setting('lue.last')::date::date, interval '1 day') s) g
        LEFT JOIN lue_staging.stg_lease sl ON sl.unit_id = su.unit_id AND g.day BETWEEN sl.start_date AND sl.end_date
        LEFT JOIN _occ_balance b ON b.lease_number = sl.lease_number AND g.day >= b.from_day AND g.day < b.to_day
        LEFT JOIN lue_dw.dim_unit du ON du.unit_nk = su.building_code || '-' || su.unit_no AND (g.day)::date >= du.effective_from AND (g.day)::date < du.effective_to
        LEFT JOIN lue_dw.dim_tenant dt ON dt.tenant_code = sl.tenant_code AND (g.day)::date >= dt.effective_from AND (g.day)::date < dt.effective_to
        LEFT JOIN lue_dw.dim_lease dl ON dl.lease_number = sl.lease_number
        LEFT JOIN lue_staging.stg_ownership dw_r ON dw_r.building_code = su.building_code AND dw_r.unit_no = su.unit_no AND dw_r.valid_from <= (g.day)::date AND (dw_r.valid_to IS NULL OR (g.day)::date < dw_r.valid_to) LEFT JOIN lue_dw.dim_owner dw ON dw.owner_code = dw_r.owner_code;
INSERT INTO lue_dw.fact_unit_occupancy_daily (snapshot_date_key, unit_key, tenant_key, lease_key, owner_key, is_occupied, contract_rent, current_lease_arrears, source_system, batch_id, loaded_at) SELECT s.snapshot_date_key, s.unit_key, s.tenant_key, s.lease_key, s.owner_key, s.is_occupied, s.contract_rent, s.current_lease_arrears, s.source_system, current_setting('lue.run_id')::bigint, current_setting('lue.loaded_at')::timestamp FROM _fact_src s WHERE NOT EXISTS (SELECT 1 FROM lue_dw.fact_unit_occupancy_daily x WHERE x.snapshot_date_key = s.snapshot_date_key AND x.unit_key = s.unit_key AND x.snapshot_date_key BETWEEN current_setting('lue.first_key')::int AND current_setting('lue.last_key')::int) ORDER BY s.snapshot_date_key, s.unit_key;
DROP TABLE IF EXISTS _fact_src;

COMMIT;
